//! Philox4x32-10 counter-based random numbers.
//!
//! Salmon, Moraes, Dror and Shaw, "Parallel random numbers: as easy as 1,
//! 2, 3", SC '11 (2011), section 3.2. Constants and round function as in
//! Random123 `philox.h`; the tests use Random123's known-answer vectors.
//! The C++ twin is `qp/philox.hpp`, and the two produce the same words.
//!
//! The output is a pure function of (key, counter), so path `p` of a Monte
//! Carlo run can be generated by any thread from `PhiloxStream::new(seed, p)`
//! and the result does not depend on the thread count. Existing engine
//! streams (xoshiro) are unchanged; switching them would move every MC
//! golden.

const M0: u32 = 0xD251_1F53;
const M1: u32 = 0xCD9E_8D57;
const W0: u32 = 0x9E37_79B9;
const W1: u32 = 0xBB67_AE85;

/// One Philox4x32 block with `rounds` rounds (10 is standard).
#[must_use]
pub fn philox4x32(mut ctr: [u32; 4], mut key: [u32; 2], rounds: u32) -> [u32; 4] {
    for r in 0..rounds {
        if r > 0 {
            key[0] = key[0].wrapping_add(W0);
            key[1] = key[1].wrapping_add(W1);
        }
        let p0 = u64::from(M0) * u64::from(ctr[0]);
        let p1 = u64::from(M1) * u64::from(ctr[2]);
        let (hi0, lo0) = ((p0 >> 32) as u32, p0 as u32);
        let (hi1, lo1) = ((p1 >> 32) as u32, p1 as u32);
        ctr = [hi1 ^ ctr[1] ^ key[0], lo1, hi0 ^ ctr[3] ^ key[1], lo0];
    }
    ctr
}

/// A stream over Philox4x32-10: key = 64-bit seed, counter = (stream id,
/// block index), two 64-bit words per block.
#[derive(Debug, Clone)]
pub struct PhiloxStream {
    key: [u32; 2],
    stream: u64,
    block: u64,
    buf: [u64; 2],
    have: usize,
}

impl PhiloxStream {
    /// Stream `stream_id` under `seed`.
    #[must_use]
    pub fn new(seed: u64, stream_id: u64) -> Self {
        Self {
            key: [seed as u32, (seed >> 32) as u32],
            stream: stream_id,
            block: 0,
            buf: [0; 2],
            have: 0,
        }
    }

    /// Position at 64-bit word `word` without generating the earlier ones.
    pub fn seek(&mut self, word: u64) {
        self.block = word / 2;
        self.have = 0;
        if word % 2 == 1 {
            self.refill();
            self.have = 1;
        }
    }

    fn refill(&mut self) {
        let out = philox4x32(
            [
                self.stream as u32,
                (self.stream >> 32) as u32,
                self.block as u32,
                (self.block >> 32) as u32,
            ],
            self.key,
            10,
        );
        self.buf = [
            (u64::from(out[1]) << 32) | u64::from(out[0]),
            (u64::from(out[3]) << 32) | u64::from(out[2]),
        ];
        self.block = self.block.wrapping_add(1);
    }

    /// Next 64-bit word.
    pub fn next_u64(&mut self) -> u64 {
        if self.have == 0 {
            self.refill();
            self.have = 2;
        }
        let w = self.buf[2 - self.have];
        self.have -= 1;
        w
    }

    /// Uniform on (0, 1): `((u >> 11) + 0.5) 2^-53`, as `qp::uniform_open53`.
    pub fn uniform(&mut self) -> f64 {
        ((self.next_u64() >> 11) as f64 + 0.5) * (1.0 / 9_007_199_254_740_992.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn random123_known_answers() {
        assert_eq!(
            philox4x32([0; 4], [0; 2], 10),
            [0x6627_e8d5, 0xe169_c58d, 0xbc57_ac4c, 0x9b00_dbd8]
        );
        assert_eq!(
            philox4x32([u32::MAX; 4], [u32::MAX; 2], 10),
            [0x408f_276d, 0x41c8_3b0e, 0xa20b_c7c6, 0x6d54_51fd]
        );
        assert_eq!(
            philox4x32(
                [0x243f_6a88, 0x85a3_08d3, 0x1319_8a2e, 0x0370_7344],
                [0xa409_3822, 0x299f_31d0],
                10
            ),
            [0xd16c_fe09, 0x94fd_cceb, 0x5001_e420, 0x2412_6ea1]
        );
    }

    #[test]
    fn seek_matches_sequential() {
        let mut a = PhiloxStream::new(42, 7);
        let seq: Vec<u64> = (0..9).map(|_| a.next_u64()).collect();
        for (i, &w) in seq.iter().enumerate() {
            let mut b = PhiloxStream::new(42, 7);
            b.seek(i as u64);
            assert_eq!(b.next_u64(), w);
        }
        assert_ne!(PhiloxStream::new(42, 8).next_u64(), seq[0]);
    }
}
